pub(super) fn reserve_reorg_cancellation(
    &self,
    old: Hash,
    target: Hash,
    generation: u64,
    cpu: Option<&ServiceMutationCpuCheckpoint>,
) -> Result<Reservation> {
    self.namespace()?;
    self.storage_context()?;
    let continuous_cpu = self.continuous_reorg_original_cpu()?;
    let mining_cpu = self.mining_reorg_original_cpu()?;
    ensure(
        continuous_cpu.is_none() || mining_cpu.is_none(),
        "OWNER_REORG_TERMINATION_CPU_REQUIRED",
    )?;
    let original_cpu = continuous_cpu
        .as_ref()
        .or_else(|| mining_cpu.as_ref().map(|(_, cpu)| cpu));
    let cpu = if let Some(original) = original_cpu {
        ensure(
            cpu.is_none_or(|provided| provided.shares_operation_with(original)),
            "OWNER_PUBLIC_SERVICE_CPU_DOMAIN",
        )?;
        Some(original)
    } else {
        cpu
    };
    let domain = mining_cpu
        .as_ref()
        .map(|(domain, _)| Ok(domain.clone()))
        .unwrap_or_else(|| self.public_service_cpu_domain());
    let reserved = match (domain, cpu) {
        (Ok(domain), Some(cpu)) => {
            ensure(
                cpu.shares_domain_with(&domain),
                "OWNER_PUBLIC_SERVICE_CPU_DOMAIN",
            )?;
            Some(cpu.reserve_reorg_termination()?)
        }
        (Ok(_), None) => return Err("OWNER_REORG_TERMINATION_CPU_REQUIRED".into()),
        (Err(error), None) if error.is(crate::ErrorCode::OwnerPublicServiceDomainUnbound) => {
            // Existing unmetered local APIs remain explicitly unmetered.
            // This branch creates no CPU account or paid-service claim.
            ensure(
                self.continuous_owner.is_none() && self.mining_owner.is_none(),
                "OWNER_REORG_TERMINATION_CPU_REQUIRED",
            )?;
            None
        }
        (Err(error), _) => return Err(error),
    };

/// The existing durable/volatile Node owner is the sole right to assign a
/// public service budget. A fresh non-continuous Node may bind its first
/// trusted service once; new listeners, restarts of a listener and local W1
/// helpers must reuse the EXACT domain for the remainder of this Node's
/// lifetime. Continuous mode additionally enforces its existing owner.
/// This does not create an account, disk journal or cross-host entitlement.
pub(crate) fn bind_public_service_cpu_domain(
    &mut self,
    cpu: &ServiceMutationCpuDomain,
) -> Result<()> {
    ensure(
        !self.public_service_epoch_unknown,
        "OWNER_PUBLIC_SERVICE_UNCLEAN_EPOCH",
    )?;
    // Cold Node::open has no live epoch reference. Its volatile unknown
    // flag alone cannot authenticate a clean prior process: the original
    // persisted active marker must fence every binder, including trusted
    // local metered helpers which do not start a public listener.
    // A current listener owns its existing reference; continuous mode
    // still has to match its original authenticated durable owner below.
    if !self.is_continuous() && self.public_service_epoch_listeners == 0 {
        let prior_epoch: bool = self.db.query_row(
            "SELECT EXISTS(SELECT 1 FROM metadata WHERE key=?1)",
            [ORDINARY_PUBLIC_EPOCH_KEY],
            |row| row.get(0),
        )?;
        ensure(!prior_epoch, "OWNER_PUBLIC_SERVICE_UNCLEAN_EPOCH")?;
    }
    ensure(
        self.continuous_owner
            .as_ref()
            .is_none_or(|owner| owner.cpu.shares_domain_with(cpu)),
        "OWNER_CONTINUOUS_SERVICE_CPU_DOMAIN",
    )?;
    match &self.public_service_cpu {
        Some(existing) => ensure(
            existing.shares_domain_with(cpu),
            "OWNER_PUBLIC_SERVICE_CPU_DOMAIN",
        ),
        None => {
            self.public_service_cpu = Some(cpu.clone());
            Ok(())
        }
    }
}
/// An existing trusted local supervisor may reconstruct a listener from the
/// Node's already bound budget; it cannot request another fresh burst.
pub fn public_service_cpu_domain(&self) -> Result<ServiceMutationCpuDomain> {
    self.public_service_cpu
        .as_ref()
        .or_else(|| self.continuous_owner.as_ref().map(|owner| &owner.cpu))
        .cloned()
        .ok_or_else(|| "OWNER_PUBLIC_SERVICE_DOMAIN_UNBOUND".into())

fn activate_packet(
    owner: &mut Owner<'_>,
    tip: Hash,
    clock: u64,
    control: &Control<'_>,
    operation: &public_v3::ServiceMutationCpuOperation,
) -> Result<Hash> {
    let owns_node_mutex = matches!(owner, Owner::Shared(_));
    let checkpoint = || operation.history_checkpoint(owns_node_mutex, &|| control.check());
    checkpoint()?;
    let active = owner.with(control, |node| {
        node.activate_observed_with_termination(
            tip,
            clock,
            &mut || {
                cut("activation_progress");
                checkpoint()
            },
            Some(&operation.checkpoint_handle()),
        )
    })?;

